<?php namespace App\Http\Controllers; use App\Models\Customer; use Illuminate\Http\Request;
class CustomerController extends Controller {public function index(){return view('customers.index',['customers'=>Customer::latest()->paginate(20)]);} public function create(){return view('customers.form',['customer'=>new Customer]);} public function store(Request $r){Customer::create($r->validate(['name'=>'required|max:255','phone'=>'nullable|max:50','email'=>'nullable|email','address'=>'nullable','opening_due'=>'nullable|numeric|min:0','status'=>'required|in:active,inactive']));return redirect()->route('customers.index')->with('success','Customer saved.');} public function edit(Customer $customer){return view('customers.form',compact('customer'));} public function update(Request $r,Customer $customer){$customer->update($r->validate(['name'=>'required|max:255','phone'=>'nullable|max:50','email'=>'nullable|email','address'=>'nullable','opening_due'=>'nullable|numeric|min:0','status'=>'required|in:active,inactive']));return redirect()->route('customers.index')->with('success','Customer updated.');} public function destroy(Customer $customer){$customer->delete();return back()->with('success','Customer removed.');} public function payment(Request $r,Customer $customer){return back()->with('success','Payment recorded. Connect customer payment ledger before production use.');}}
